"""
Persist mix timing PCM for desktop QC waveform reuse.

Writes mono PCM16 @ 16 kHz WAV (same clock as TEN/Qwen island ASR).
Never cache Demucs vocals-only buffers — callers must pass the mix used for
cue paint / acoustic ends.

Cache root preference (never the film/output folder):
1. TRANSUB_TIMING_PCM_CACHE env (desktop sets this under writableRoot/cache/timing-pcm)
2. TRANSUB_ENGINE_TEMP env
3. system temp / transub-timing-pcm
"""
from __future__ import annotations

import logging
import os
import tempfile
import threading
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Iterator

import numpy as np

_log = logging.getLogger("transub_engine.audio.timing_pcm_cache")

SAMPLE_RATE = 16000

_lock = threading.Lock()
_active_out: str | None = None
_last_written: str | None = None


def resolve_timing_pcm_cache_root() -> Path:
    """App-owned cache root — must not land beside user media."""
    for key in ("TRANSUB_TIMING_PCM_CACHE", "TRANSUB_ENGINE_TEMP"):
        raw = str(os.environ.get(key) or "").strip()
        if raw:
            return Path(raw)
    return Path(tempfile.gettempdir()) / "transub-timing-pcm"


def default_timing_pcm_path(media_path: str, output_dir: str | Path | None = None) -> Path:
    """
    Resolve ``{cacheRoot}/.transub-cache/{stem}.timing-16k.wav``.

    ``output_dir`` is accepted for API compatibility but is intentionally ignored so
    timing PCM never pollutes the subtitle output / film directory.
    """
    del output_dir  # kept for call-site compatibility; never use as cache root
    media = Path(str(media_path or "").strip())
    stem = media.stem or "media"
    return resolve_timing_pcm_cache_root() / ".transub-cache" / f"{stem}.timing-16k.wav"


@contextmanager
def timing_pcm_cache_target(path: str | Path | None) -> Iterator[str | None]:
    """Bind the destination path for the current ASR job (thread-safe enough for job worker)."""
    global _active_out, _last_written
    target = str(path or "").strip() or None
    with _lock:
        prev = _active_out
        _active_out = target
        _last_written = None
    try:
        yield target
    finally:
        with _lock:
            _active_out = prev


def last_written_timing_pcm() -> str | None:
    with _lock:
        return _last_written


def write_mix_timing_pcm(audio_f32: Any, *, out_path: str | Path | None = None) -> str | None:
    """
    Write float32 mono PCM as 16-bit WAV for QC. Uses the active cache target
    when ``out_path`` is omitted.
    """
    global _last_written
    with _lock:
        dest = str(out_path or _active_out or "").strip()
    if not dest:
        return None
    try:
        pcm = np.asarray(audio_f32, dtype=np.float32).reshape(-1)
    except Exception as err:
        _log.debug("timing PCM cache: bad buffer (%s)", err)
        return None
    if pcm.size < SAMPLE_RATE // 10:
        _log.debug("timing PCM cache: buffer too short (%d samples)", int(pcm.size))
        return None

    path = Path(dest)
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        import wave

        i16 = np.clip(np.rint(pcm * 32767.0), -32768, 32767).astype(np.int16)
        with wave.open(str(path), "wb") as wf:
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(int(SAMPLE_RATE))
            wf.writeframes(i16.tobytes())
        with _lock:
            _last_written = str(path)
        mb = path.stat().st_size / (1024.0 * 1024.0)
        _log.info(
            "timing PCM cache written: %s | samples=%d | ~%.1f MB (mix, for QC waveform)",
            path.name,
            int(pcm.size),
            mb,
        )
        return str(path)
    except Exception as err:
        _log.warning("timing PCM cache write failed (%s): %s", path, err)
        try:
            if path.is_file():
                path.unlink()
        except Exception:
            pass
        return None
